import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        String p = next();
        long k = Long.parseLong(next());
        String[] w = new String[(int) k];
        for (int i = 0; i < w.length; i++) w[i] = next();

        boolean ok = p.length() == k;
        Map<Character, String> toWord = new HashMap<>();
        Map<String, Character> toLetter = new HashMap<>();
        for (int i = 0; ok && i < k; i++) {
            char ch = p.charAt(i);
            if (toWord.containsKey(ch) && !toWord.get(ch).equals(w[i])) ok = false;
            else if (toLetter.containsKey(w[i]) && toLetter.get(w[i]) != ch) ok = false;
            else {
                toWord.put(ch, w[i]);
                toLetter.put(w[i], ch);
            }
        }
        System.out.println(ok ? "yes" : "no");
    }
}
